package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// RealClock uses the system clock.
type RealClock struct{}

// Now returns the current wall-clock time.
func (RealClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It permits bursts up to the bucket capacity and refills tokens
// continuously at rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by New when arguments are out of range.
var ErrInvalidConfig = errors.New("ratelimit: invalid configuration")

// New creates a Limiter with the given burst capacity, refill rate
// (tokens per second), and clock. capacity must be > 0, rate must be > 0,
// and clock must be non-nil.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("%w: capacity must be > 0, got %d", ErrInvalidConfig, capacity)
	}
	if rate <= 0 {
		return nil, fmt.Errorf("%w: rate must be > 0, got %v", ErrInvalidConfig, rate)
	}
	if clock == nil {
		return nil, fmt.Errorf("%w: clock must not be nil", ErrInvalidConfig)
	}
	return &Limiter{
		tokens:   float64(capacity),
		capacity: float64(capacity),
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// Tokens refill continuously at the configured rate based on elapsed
// time since the last refill.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = minF(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	if elapsed > 0 {
		return minF(l.capacity, l.tokens+elapsed*l.rate)
	}
	return l.tokens
}

func minF(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
