// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. Implementations must return
// monotonically non-decreasing values for correct limiter behavior.
type Clock interface {
	Now() time.Time
}

// SystemClock is a Clock backed by the wall clock.
type SystemClock struct{}

// Now implements Clock.
func (SystemClock) Now() time.Time { return time.Now() }

type clockFunc struct{ f func() time.Time }

func (c clockFunc) Now() time.Time { return c.f() }

// ClockFunc adapts a function to a Clock.
func ClockFunc(f func() time.Time) Clock { return clockFunc{f} }

// ErrInvalidCapacity is returned by New when capacity <= 0.
var ErrInvalidCapacity = errors.New("ratelimit: capacity must be > 0")

// ErrInvalidRate is returned by New when rate <= 0.
var ErrInvalidRate = errors.New("ratelimit: rate must be > 0")

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at Rate tokens per second,
// up to Capacity tokens.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

// New returns a Limiter with the given capacity (tokens) and refill
// rate (tokens per second). The bucket starts full.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if rate <= 0 {
		return nil, ErrInvalidRate
	}
	if clock == nil {
		clock = SystemClock{}
	}
	return &Limiter{
		tokens:   capacity,
		last:     clock.Now(),
		capacity: capacity,
		rate:     rate,
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed now. If so, the
// tokens are deducted; otherwise the bucket is left unchanged.
func (l *Limiter) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// RetryIn returns the duration until n tokens would be available,
// assuming no further consumption. It returns 0 if n is available now.
func (l *Limiter) RetryIn(n float64) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n <= l.tokens {
		return 0
	}
	return time.Duration((n - l.tokens) / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
