// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds at most burst tokens and refills at rate tokens per second.
type Limiter struct {
	mu        sync.Mutex
	tokens    float64
	burst     float64
	rate      float64 // tokens per second
	last      time.Time
	clock     Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
)

// New returns a Limiter with the given refill rate (tokens per second) and
// burst capacity, starting full. It uses the real clock.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable Clock. The clock must not be nil.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	return &Limiter{
		tokens: float64(burst),
		burst:  float64(burst),
		rate:   rate,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// refill advances the bucket to time now, adding accrued tokens.
// The caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time.Now.
func (l *Limiter) AllowN(n int) bool {
	return l.allowAt(l.clock.Now(), n)
}

// Allow reports whether one token may be consumed at time.Now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) allowAt(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}
